def cmp_semver(a, b):
    def parse(version):
        version = version.split("+", 1)[0]
        core, sep, prerelease = version.partition("-")
        major, minor, patch = map(int, core.split("."))
        return (major, minor, patch), (prerelease.split(".") if sep else None)

    (a_core, a_pre), (b_core, b_pre) = parse(a), parse(b)

    if a_core < b_core:
        return -1
    if a_core > b_core:
        return 1

    if a_pre is None:
        return 0 if b_pre is None else 1
    if b_pre is None:
        return -1

    for x, y in zip(a_pre, b_pre):
        x_num = all("0" <= c <= "9" for c in x)
        y_num = all("0" <= c <= "9" for c in y)

        if x_num and y_num:
            if int(x) < int(y):
                return -1
            if int(x) > int(y):
                return 1
        elif x_num != y_num:
            return -1 if x_num else 1
        elif x < y:
            return -1
        elif x > y:
            return 1

    if len(a_pre) < len(b_pre):
        return -1
    if len(a_pre) > len(b_pre):
        return 1
    return 0

