import re


def gitignore_match(pattern, path):
    if not pattern or not path:
        return False

    directory_only = pattern.endswith("/")
    anchored = pattern.startswith("/") or (
        "/" in pattern.rstrip("/")
    )

    pattern = pattern.lstrip("/")
    if directory_only:
        pattern = pattern[:-1]

    if directory_only and not path.endswith("/"):
        return False

    target = path[:-1] if path.endswith("/") else path

    def class_regex(content):
        if not content:
            return r"\["
        negated = content[0] in "!^"
        if negated:
            content = content[1:]
        chars = []
        for ch in content:
            if ch == "\\":
                chars.append(r"\\")
            elif ch in "[]^":
                chars.append("\\" + ch)
            else:
                chars.append(ch)
        return "[" + ("^" if negated else "") + "".join(chars) + "]"

    def glob_regex(text):
        out = []
        i = 0

        while i < len(text):
            ch = text[i]

            if ch == "*" and i + 1 < len(text) and text[i + 1] == "*":
                if i + 2 < len(text) and text[i + 2] == "/":
                    out.append(r"(?:[^/]+/)*")
                    i += 3
                else:
                    out.append(r".*")
                    i += 2
                continue

            if ch == "*":
                out.append(r"[^/]*")
            elif ch == "?":
                out.append(r"[^/]")
            elif ch == "[":
                end = text.find("]", i + 1)
                if end == -1:
                    out.append(r"\[")
                else:
                    out.append(class_regex(text[i + 1:end]))
                    i = end
            else:
                out.append(re.escape(ch))

            i += 1

        return "".join(out)

    if not anchored and "/" not in pattern:
        regex = r"(?:^|.*/)" + glob_regex(pattern)
    elif pattern == "**":
        regex = r".*"
    elif pattern.endswith("/**"):
        prefix = pattern[:-3]
        regex = glob_regex(prefix) + (r"/.*" if prefix else r".*")
    else:
        regex = glob_regex(pattern)

    return re.fullmatch(regex, target) is not None

