def parse_range(header, size):
    if not isinstance(header, str) or not isinstance(size, int) or isinstance(size, bool) or size < 0:
        return None

    header = header.strip(" \t")
    eq = header.find("=")
    if eq <= 0 or header.find("=", eq + 1) != -1:
        return None
    if header[:eq].lower() != "bytes":
        return None

    range_set = header[eq + 1:]
    if not range_set:
        return None

    def decimal(value):
        number = 0
        for char in value:
            if char < "0" or char > "9":
                return None
            number = number * 10 + (ord(char) - ord("0"))
        return number

    result = []

    for item in range_set.split(","):
        item = item.strip(" \t")
        if not item:
            return None

        hyphen = item.find("-")
        if hyphen < 0 or hyphen != item.rfind("-"):
            return None

        first = item[:hyphen]
        last = item[hyphen + 1:]

        if not first and not last:
            return None

        if not first:
            suffix_length = decimal(last)
            if suffix_length is None:
                return None
            if suffix_length == 0 or size == 0:
                continue
            start = max(0, size - suffix_length)
            result.append((start, size - 1))
            continue

        start = decimal(first)
        if start is None:
            return None

        if start >= size:
            continue

        if not last:
            end = size - 1
        else:
            end = decimal(last)
            if end is None:
                return None
            if end < start:
                continue
            end = min(end, size - 1)

        result.append((start, end))

    return result if result else None

