def unified_diff(a, b, context=3):
    if a == b:
        return []

    context = max(0, context)
    n, m = len(a), len(b)

    lcs = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        for j in range(m - 1, -1, -1):
            if a[i] == b[j]:
                lcs[i][j] = lcs[i + 1][j + 1] + 1
            else:
                lcs[i][j] = max(lcs[i + 1][j], lcs[i][j + 1])

    entries = []
    i = j = 0
    while i < n or j < m:
        if i < n and j < m and a[i] == b[j]:
            entries.append((" ", a[i]))
            i += 1
            j += 1
        elif j == m or (i < n and lcs[i + 1][j] >= lcs[i][j + 1]):
            entries.append(("-", a[i]))
            i += 1
        else:
            entries.append(("+", b[j]))
            j += 1

    changed = [i for i, (tag, _) in enumerate(entries) if tag != " "]
    intervals = []
    for index in changed:
        start = max(0, index - context)
        end = min(len(entries), index + context + 1)
        if intervals and start <= intervals[-1][1]:
            intervals[-1] = (intervals[-1][0], max(intervals[-1][1], end))
        else:
            intervals.append((start, end))

    old_prefix = [0]
    new_prefix = [0]
    for tag, _ in entries:
        old_prefix.append(old_prefix[-1] + (tag != "+"))
        new_prefix.append(new_prefix[-1] + (tag != "-"))

    def clean(line):
        if line.endswith("\n"):
            line = line[:-1]
            if line.endswith("\r"):
                line = line[:-1]
        return line

    result = []
    for start, end in intervals:
        old_before = old_prefix[start]
        new_before = new_prefix[start]
        old_len = old_prefix[end] - old_before
        new_len = new_prefix[end] - new_before

        old_start = old_before + 1 if old_len else old_before
        new_start = new_before + 1 if new_len else new_before

        result.append(
            f"@@ -{old_start},{old_len} +{new_start},{new_len} @@"
        )
        result.extend(tag + clean(line) for tag, line in entries[start:end])

    return result

