class _Node:
    __slots__ = ("key", "value", "freq", "prev", "next")

    def __init__(self, key=None, value=None, freq=1):
        self.key = key
        self.value = value
        self.freq = freq
        self.prev = None
        self.next = None


class _FrequencyList:
    __slots__ = ("head", "tail")

    def __init__(self):
        self.head = _Node()
        self.tail = _Node()
        self.head.next = self.tail
        self.tail.prev = self.head

    def add_first(self, node):
        node.next = self.head.next
        node.prev = self.head
        self.head.next.prev = node
        self.head.next = node

    def remove(self, node):
        node.prev.next = node.next
        node.next.prev = node.prev

    def pop_last(self):
        node = self.tail.prev
        if node is self.head:
            return None
        self.remove(node)
        return node

    def empty(self):
        return self.head.next is self.tail


class LFUCache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.size = 0
        self.min_freq = 0
        self.nodes = {}
        self.freq_lists = {}

    def _touch(self, node):
        freq = node.freq
        freq_list = self.freq_lists[freq]
        freq_list.remove(node)

        if freq_list.empty():
            del self.freq_lists[freq]
            if self.min_freq == freq:
                self.min_freq += 1

        node.freq += 1
        self.freq_lists.setdefault(node.freq, _FrequencyList()).add_first(node)

    def get(self, key):
        node = self.nodes.get(key)
        if node is None:
            return -1
        self._touch(node)
        return node.value

    def put(self, key, value):
        if self.capacity <= 0:
            return

        node = self.nodes.get(key)
        if node is not None:
            node.value = value
            self._touch(node)
            return

        if self.size >= self.capacity:
            freq_list = self.freq_lists[self.min_freq]
            evicted = freq_list.pop_last()
            del self.nodes[evicted.key]
            self.size -= 1
            if freq_list.empty():
                del self.freq_lists[self.min_freq]

        node = _Node(key, value, 1)
        self.nodes[key] = node
        self.freq_lists.setdefault(1, _FrequencyList()).add_first(node)
        self.min_freq = 1
        self.size += 1

