import heapq

def topk(stream, k):
    if k <= 0:
        return []

    heap = []
    for index, (value, label) in enumerate(stream):
        entry = (value, -index, label)
        if len(heap) < k:
            heapq.heappush(heap, entry)
        elif entry[:2] > heap[0][:2]:
            heapq.heapreplace(heap, entry)

    heap.sort(key=lambda item: (item[0], item[1]), reverse=True)
    return [(value, label) for value, _, label in heap]

