import re
from datetime import datetime, time, timedelta

def next_fire(expr, after):
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("cron expression must contain five fields")

    ranges = [(0, 59), (0, 23), (1, 31), (1, 12), (0, 6)]

    def parse_field(text, lo, hi):
        if not text:
            raise ValueError("malformed cron field")

        values = set()
        for part in text.split(","):
            if not part:
                raise ValueError("malformed cron field")

            if part.count("/") > 1:
                raise ValueError("malformed cron field")

            if "/" in part:
                base, step_text = part.split("/")
                if not step_text.isdigit():
                    raise ValueError("malformed cron field")
                step = int(step_text)
                if step <= 0:
                    raise ValueError("invalid cron step")
            else:
                base, step = part, 1

            if base == "*":
                start, end = lo, hi
            elif re.fullmatch(r"\d+-\d+", base):
                a, b = map(int, base.split("-"))
                if a > b:
                    raise ValueError("invalid cron range")
                start, end = a, b
            elif "/" in part:
                raise ValueError("malformed cron field")
            elif re.fullmatch(r"\d+", base):
                if step != 1:
                    raise ValueError("malformed cron field")
                start = end = int(base)
            else:
                raise ValueError("malformed cron field")

            if start < lo or end > hi:
                raise ValueError("cron value out of range")

            values.update(range(start, end + 1, step))

        if not values:
            raise ValueError("empty cron field")
        return values

    minute = parse_field(fields[0], *ranges[0])
    hour = parse_field(fields[1], *ranges[1])
    dom = parse_field(fields[2], *ranges[2])
    month = parse_field(fields[3], *ranges[3])
    dow = parse_field(fields[4], *ranges[4])

    dom_restricted = fields[2] != "*"
    dow_restricted = fields[4] != "*"
    minutes = sorted(h * 60 + m for h in hour for m in minute)

    current = after.date()
    tzinfo = after.tzinfo

    for _ in range(146097):
        if current.month in month:
            dom_match = current.day in dom
            dow_match = ((current.weekday() + 1) % 7) in dow

            if (
                (dom_restricted and dow_restricted and (dom_match or dow_match))
                or (dom_restricted and not dow_restricted and dom_match)
                or (not dom_restricted and dow_restricted and dow_match)
                or (not dom_restricted and not dow_restricted)
            ):
                for minute_of_day in minutes:
                    candidate = datetime.combine(
                        current,
                        time(minute_of_day // 60, minute_of_day % 60),
                        tzinfo=tzinfo,
                    )
                    if candidate > after:
                        return candidate

        if current == datetime.max.date():
            break
        current += timedelta(days=1)

    raise ValueError("no matching datetime")

