            raise ValueError("n must be non-negative")
        self._parent = list(range(n))
        self._size = [1] * n
        self._history = []
        self._components = n

    def find(self, x):
        while self._parent[x] != x:
            x = self._parent[x]
        return x

    def union(self, a, b):
        ra = self.find(a)
        rb = self.find(b)

        if ra == rb:
            return False

        if self._size[ra] < self._size[rb]:
            ra, rb = rb, ra

        self._history.append((rb, ra, self._size[ra]))
        self._parent[rb] = ra
        self._size[ra] += self._size[rb]
        self._components -= 1
        return True

    def snapshot(self):
        return self._Snapshot(self, len(self._history))

    def rollback(self, token):
        if not isinstance(token, self._Snapshot) or token._owner is not self:
            raise ValueError("invalid snapshot token")
        if token._index > len(self._history):
            raise ValueError("snapshot has already been invalidated")

        while len(self._history) > token._index:
            child, root, old_size = self._history.pop()
            self._parent[child] = child
            self._size[root] = old_size
            self._components += 1

    def components(self):
        return self._components

