import threading


def transfer_all(accounts, ops):
    balances = list(accounts)
    locks = [threading.Lock() for _ in balances]

    def transfer(src, dst, amount):
        if src == dst:
            with locks[src]:
                if balances[src] >= amount:
                    balances[src] -= amount
                    balances[dst] += amount
            return

        first, second = sorted((src, dst))
        with locks[first]:
            with locks[second]:
                if balances[src] >= amount:
                    balances[src] -= amount
                    balances[dst] += amount

    threads = [
        threading.Thread(target=transfer, args=(src, dst, amount))
        for src, dst, amount in ops
    ]

    for thread in threads:
        thread.start()
    for thread in threads:
        thread.join()

    return balances

