    if not s:
        raise ValueError("empty string")
    if not alphabet or len(set(alphabet)) != len(alphabet):
        raise ValueError("alphabet must contain distinct characters")
    if len(alphabet) < 2:
        raise ValueError("alphabet must contain at least two characters")

    negative = s[0] == '-'
    digits = s[1:] if negative else s

    if not digits:
        raise ValueError("missing digits")

    values = {char: value for value, char in enumerate(alphabet)}
    number = 0
    base = len(alphabet)

    for char in digits:
        if char not in values:
            raise ValueError(f"invalid character: {char!r}")
        number = number * base + values[char]

    return -number if negative else number

