const fragments = new WeakMap();

function sqlTag(strings, ...interpolations) {
  const parts = [];

  for (let i = 0; i < strings.length; i++) {
    parts.push(strings[i]);

    if (i < interpolations.length) {
      const value = interpolations[i];

      if (fragments.has(value)) {
        parts.push(...fragments.get(value));
      } else if (Array.isArray(value)) {
        parts.push("(");
        value.forEach((item, index) => {
          if (index > 0) parts.push(", ");
          parts.push({ value: item });
        });
        parts.push(")");
      } else {
        parts.push({ value });
      }
    }
  }

  let index = 0;
  const values = [];
  let text = "";

  for (const part of parts) {
    if (typeof part === "string") {
      text += part;
    } else {
      values.push(part.value);
      text += `$${++index}`;
    }
  }

  const result = { text, values };
  fragments.set(result, parts);
  return result;
}

module.exports = sqlTag;

