function* zipLongest(fill, ...iterables) {
  const iterators = iterables.map(iterable => iterable[Symbol.iterator]());
  const active = iterators.map(() => true);
  let remaining = iterators.length;

  while (remaining > 0) {
    const row = new Array(iterators.length);
    let yieldedValue = false;

    for (let i = 0; i < iterators.length; i++) {
      if (!active[i]) {
        row[i] = fill;
        continue;
      }

      const step = iterators[i].next();

      if (step.done) {
        active[i] = false;
        remaining--;
        row[i] = fill;
      } else {
        row[i] = step.value;
        yieldedValue = true;
      }
    }

    if (!yieldedValue) return;
    yield row;
  }
}

module.exports = zipLongest;

