function toposortTasks(tasks) {
  return new Promise((resolve, reject) => {
    const names = Object.keys(tasks);
    const nameSet = new Set(names);
    const dependencies = new Map();
    const dependents = new Map();
    const indegree = new Map();

    for (const name of names) {
      const deps = Array.from(new Set(tasks[name].deps || []));
      for (const dep of deps) {
        if (!nameSet.has(dep)) {
          reject(new Error(`unknown dependency: ${dep}`));
          return;
        }
      }
      dependencies.set(name, deps);
      dependents.set(name, []);
      indegree.set(name, deps.length);
    }

    for (const name of names) {
      for (const dep of dependencies.get(name)) {
        dependents.get(dep).push(name);
      }
    }

    const checkIndegree = new Map(indegree);
    const queue = names.filter(name => checkIndegree.get(name) === 0);
    let visited = 0;

    while (queue.length) {
      const name = queue.shift();
      visited++;

      for (const dependent of dependents.get(name)) {
        const count = checkIndegree.get(dependent) - 1;
        checkIndegree.set(dependent, count);
        if (count === 0) queue.push(dependent);
      }
    }

    if (visited !== names.length) {
      reject(new Error("dependency cycle detected"));
      return;
    }

    if (names.length === 0) {
      resolve({});
      return;
    }

    const remaining = new Map(indegree);
    const failedDependency = new Map(names.map(name => [name, false]));
    const results = {};
    let settled = 0;
    let rejected = false;

    const setValue = (object, key, value) => {
      Object.defineProperty(object, key, {
        value,
        enumerable: true,
        configurable: true,
        writable: true
      });
    };

    const settle = (name, success, value) => {
      if (success) {
        setValue(results, name, value);
      } else if (!rejected) {
        rejected = true;
        reject(value);
      }

      settled++;

      for (const dependent of dependents.get(name)) {
        remaining.set(dependent, remaining.get(dependent) - 1);
        if (!success) failedDependency.set(dependent, true);

        if (remaining.get(dependent) === 0) {
