type IsAny<T> = 0 extends 1 & T ? true : false;

type IsExactlyVoid<T> =
  IsAny<T> extends true
    ? false
    : [T] extends [void]
      ? [void] extends [T]
        ? true
        : false
      : false;

type EmitArgs<T> = IsExactlyVoid<T> extends true ? [] : [payload: T];

export class Bus<E extends Record<string, unknown>> {
  private readonly handlers = new Map<
    PropertyKey,
    Set<(...args: any[]) => void>
  >();

  on<K extends keyof E>(
    k: K,
    fn: (payload: E[K]) => void,
  ): () => void {
    const key = k as PropertyKey;
    let set = this.handlers.get(key);

    if (!set) {
      set = new Set();
      this.handlers.set(key, set);
    }

    const handler = fn as (...args: any[]) => void;
    set.add(handler);

    return () => {
      set!.delete(handler);
      if (set!.size === 0) {
        this.handlers.delete(key);
      }
    };
  }

  emit<K extends keyof E>(
    k: K,
    ...args: EmitArgs<E[K]>
  ): void {
    const set = this.handlers.get(k as PropertyKey);
    if (!set) return;

    for (const handler of [...set]) {
      handler(args[0]);
    }
  }
}

