type ParamName<Segment extends string> =
  Segment extends `:${infer Name}`
    ? Name extends ""
      ? never
      : Name
    : never;

type ParamNames<Path extends string> =
  Path extends `${infer Segment}/${infer Rest}`
    ? ParamName<Segment> | ParamNames<Rest>
    : ParamName<Path>;

