  [ParamNames<Path>] extends [never]
    ? () => string
    : (params: RouteParams<Path>) => string;

export function defineRoutes<const Routes extends Record<string, string>>(
  routes: Routes
): {
  [Name in keyof Routes]: RouteFunction<Routes[Name] & string>;
} {
  const result = {} as {
    [Name in keyof Routes]: RouteFunction<Routes[Name] & string>;
  };

  for (const key of Object.keys(routes) as Array<keyof Routes>) {
    const path = routes[key] as string;

    result[key] = ((params?: Record<string, string>) =>
      path.replace(
        /:([^/]+)/g,
        (_match: string, name: string) => params?.[name] ?? ""
      )) as RouteFunction<Routes[typeof key] & string>;
  }

  return result;
}

